const D = { layers: 14, scale: 1, energy: .6, density: .5, hue: 212, speed: 1, x: .3, y: .45, alpha: 1, style: 'etched', pattern: 'ladder', act: 'forge', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl=(v,a,b)=>v<a?a:v>b?b:v, md=(a,n)=>((a%n)+n)%n, TAU=Math.PI*2;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const hsb2rgb=(h,s,b)=>{ h=md(h,360)/60; s=cl(s,0,100)/100; b=cl(b,0,100)/100;
  const c=b*s, x=c*(1-Math.abs((h%2)-1)), m=b-c; let r,g,l;
  if(h<1){r=c;g=x;l=0;} else if(h<2){r=x;g=c;l=0;} else if(h<3){r=0;g=c;l=x;}
  else if(h<4){r=0;g=x;l=c;} else if(h<5){r=x;g=0;l=c;} else {r=c;g=0;l=x;}
  return [(r+m)*255,(g+m)*255,(l+m)*255]; };
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width, Hh=height;
const sty=P.style, pat=P.pattern, act=P.act;
const lay=cl(P.layers,2,40), sc=cl(P.scale,.35,2.6), al=cl(P.alpha,0,1);
const dens=cl(P.density,0,1), spd=cl(P.speed,.1,4), en=cl(P.energy,0,1);
const H=md(P.hue,360), T=K.t*spd;
const TD=K.t*(.45+.55*Math.min(spd,3));

S.bass=(S.bass||0)*.86+(A.bass||0)*.14;
S.tre=(S.tre||0)*.86+(A.treble||0)*.14;
S.rms=(S.rms||0)*.9+(A.rms||0)*.1;

// ---- seeded wrapping fBm field, built once per seed ----
const NZ=160;
if(S.nzK!==P.seed || !S.nz){ S.nzK=P.seed; const F=new Float32Array(NZ*NZ); let amp=1, tot=0;
  for(let o=0;o<4;o++){ const per=4<<o, cell=NZ/per;
    const lv=new Float32Array(per*per);
    for(let k=0;k<per*per;k++) lv[k]=fr(o*977.3+k*1.317+3.7);
    for(let j=0;j<NZ;j++){ const gy=j/cell, jy=Math.floor(gy), fy=gy-jy, vv=fy*fy*(3-2*fy);
      const j0=(jy%per)*per, j1=((jy+1)%per)*per;
      for(let i=0;i<NZ;i++){ const gx=i/cell, ix=Math.floor(gx), fx=gx-ix, uu=fx*fx*(3-2*fx);
        const i0=ix%per, i1=(ix+1)%per;
        const a=lv[j0+i0], b=lv[j0+i1], c=lv[j1+i0], d=lv[j1+i1];
        F[j*NZ+i]+=amp*(a+(b-a)*uu+(c-a)*vv+(a-b-c+d)*uu*vv); } }
    tot+=amp; amp*=0.52; }
  for(let k=0;k<NZ*NZ;k++) F[k]=F[k]/tot;
  S.nz=F; }
const NF=S.nz, CEL=NZ/4;
// x,y in field units (period 4.0)
const nzAt=(x,y)=>{ x*=CEL; y*=CEL;
  let xi=Math.floor(x), yi=Math.floor(y); const fx=x-xi, fy=y-yi;
  xi=md(xi,NZ); yi=md(yi,NZ); const x1=(xi+1)%NZ, y1=(yi+1)%NZ, r0=yi*NZ, r1=y1*NZ;
  const a=NF[r0+xi], b=NF[r0+x1], c=NF[r1+xi], d=NF[r1+x1];
  return a+(b-a)*fx+(c-a)*fy+(a-b-c+d)*fx*fy; };

// ---- coarse buffer ----
const BW=200, BH=cl(Math.round(BW*Hh/Math.max(1,W)),60,200);
if(!S.g || S.gk!==BW+'x'+BH){ if(S.g&&S.g.remove)S.g.remove();
  S.g=createGraphics(BW,BH); S.gk=BW+'x'+BH; S.q=new Float32Array(BW*BH); S.col=new Float32Array(BW*2); }
const G=S.g, Q=S.q, CT=S.col;

// ---- dramaturgy: acts + section arc ----
const sec=((K.section|0)%8+8)%8;
const secF=.85+.30*Math.sin(sec*1.1+.7);
let etchD, specAmt, relief, lightRate;
if(act==='etch'){ etchD=.6+1.9*(.5+.5*Math.sin(sec*.9+T*.021)); specAmt=.55; relief=1.15; lightRate=.62; }
else if(act==='polish'){ etchD=1.0; specAmt=1.5; relief=.62; lightRate=1.7; }
else { etchD=1.0+.45*Math.sin(T*.037+sec); specAmt=.95; relief=1.0; lightRate=1.0; }
specAmt*=(.35+1.15*en)*(.7+.5*K.intensity);
specAmt+=S.tre*.5*en;

// ---- band profile LUT (flat-topped tanh square) ----
const sh=cl(1.5+2.8*(dens*.5+.5)*etchD,.35,7);
const shK=Math.round(sh*80);
if(S.profK!==shK || !S.pr){ S.profK=shK; const NP=512; S.pr=new Float32Array(NP); S.pd=new Float32Array(NP);
  const TH=Math.tanh(sh);
  for(let k=0;k<NP;k++){ const f=k/NP, cw=Math.cos(f*TAU), tt=Math.tanh(cw*sh);
    S.pr[k]=tt/TH; S.pd[k]=(1-tt*tt)*sh*(-Math.sin(f*TAU)*TAU)/TH; } }
const PR=S.pr, PD=S.pd;

// ---- camera drift over the billet (incommensurate, never re-phases) ----
const dxA=.9*Math.sin(TD*.13)+.5*Math.sin(TD*.31+1.7)+.32*Math.sin(TD*.53);
const dyA=.9*Math.cos(TD*.11+2.1)+.5*Math.sin(TD*.27+.4)+.28*Math.sin(TD*.47+3.3);
const fq=cl(.62/sc,.12,3.2);
const pMot=(pat==='wild')?.42:1;

const camX=1.31+dxA*.055*fq*pMot+.0016*TD*fq*pMot, camY=2.07+dyA*.055*fq*pMot;
// warp offset creeps on its own rates — the layers keep being drawn out under the hammer.
// wdN/wdM are unitless; the noise warp needs FIELD units (hence *fq), the ladder/twist
// terms need a PATTERN PHASE — never share one number between those two scales.
const wdN=.34*Math.sin(TD*.071+.9)+.19*Math.sin(TD*.163+2.4);
const wdM=.34*Math.cos(TD*.059)+.19*Math.sin(TD*.137+1.2);
const wdx=wdN*.085*fq*pMot, wdy=wdM*.085*fq*pMot;
const pdx=wdN*.030, pdy=wdM*.030;

// ---- raking light: azimuth orbits, elevation drifts -> highlight travels the bands ----
const lAz=cl(P.x,0,1)*TAU + .0135*TD*lightRate + .26*Math.sin(TD*.041*lightRate) + .13*Math.sin(TD*.097*lightRate+1.1) + .07*Math.sin(TD*.163*lightRate+2.6);
const lx=Math.cos(lAz), ly=Math.sin(lAz);
const tilt=(cl(P.y,0,1)-.5)*1.1 + .085*Math.sin(TD*.053*lightRate+.6) + .04*Math.sin(TD*.113*lightRate+2.2) + .03*K.swell;

// ---- style: metal table (all offsets from hue so hue re-tints the whole alloy) ----
const MET=[[0,0,0],[0,0,0],[0,0,0]]; let DK, spTint, grainAmt=.055, xray=0, inkish=0, satMul=1;
if(sty==='mokume'){
  DK=hsb2rgb(H+70,42,9);
  MET[0]=hsb2rgb(H+168,60,58); MET[1]=hsb2rgb(H+188,11,72); MET[2]=hsb2rgb(H+193,55,66);
  spTint=[255,244,214]; grainAmt=.06;
} else if(sty==='nitre'){
  DK=hsb2rgb(H+8,58,12);
  MET[0]=hsb2rgb(H+193,62,72); MET[1]=hsb2rgb(H+72,48,44); MET[2]=hsb2rgb(H+2,66,54);
  spTint=[228,238,255]; grainAmt=.05;
} else if(sty==='xray'){
  DK=hsb2rgb(H-4,58,9); xray=1;
  MET[0]=hsb2rgb(H-24,16,96); MET[1]=hsb2rgb(H-14,22,88); MET[2]=hsb2rgb(H-30,10,99);
  spTint=[210,240,255]; grainAmt=.03;
} else if(sty==='ink'){
  DK=hsb2rgb(H-188,32,13); inkish=1; satMul=.5;
  MET[0]=hsb2rgb(H-174,9,88); MET[1]=hsb2rgb(H-180,13,83); MET[2]=hsb2rgb(H-168,6,91);
  spTint=[250,246,236]; grainAmt=.11;
} else { // etched — pattern-welded steel, ferric bite
  DK=hsb2rgb(H,27,11);
  MET[0]=hsb2rgb(H-8,8,74); MET[1]=hsb2rgb(H-2,11,67); MET[2]=hsb2rgb(H+7,5,79);
  spTint=[255,250,240]; grainAmt=.055;
}

// ---- per-column pattern terms (pattern depends on x only for ladder/twist) ----
const rungs=Math.round(2+dens*9)*(1/Math.max(.35,sc));
const turns=(1.1+dens*2.6)/Math.max(.35,sc);
const ladAmp=2.4*secF, twZ=.30;
for(let i=0;i<BW;i++){
  const xx=i/BW;
  if(pat==='ladder'){ const s=md(xx*rungs+pdx,1); CT[i*2]=ladAmp*Math.abs(s*2-1); CT[i*2+1]=0; }
  else if(pat==='twist'){ const th=xx*turns*TAU+pdx*1.4; CT[i*2]=Math.cos(th); CT[i*2+1]=Math.sin(th); }
  else { CT[i*2]=0; CT[i*2+1]=0; }
}
// raindrop: a few drilled dimples, static in billet space, so they drift with the camera
const NDR=Math.round(4+dens*7);
if(S.drK!==P.seed+'|'+NDR){ S.drK=P.seed+'|'+NDR; const dr=new Float32Array(NDR*3);
  for(let k=0;k<NDR;k++){ dr[k*3]=fr(k*3.1+40); dr[k*3+1]=fr(k*3.1+41); dr[k*3+2]=.05+.10*fr(k*3.1+42); }
  S.dr=dr; }
const DR=S.dr;

// ---- PASS 1: the fold coordinate q, in layer units ----
const asp=BH/BW;
for(let j=0;j<BH;j++){
  const yy=j/BH, gy=(j/BW)*fq+camY;
  for(let i=0;i<BW;i++){
    const xx=i/BW, gx=xx*fq+camX;
    const w1=nzAt(gx+wdx, gy+wdy)-.5;
    const w2=nzAt(gx*2.13+31.7-wdy, gy*2.13+17.3+wdx)-.5;
    let q;
    if(pat==='wild') q=(yy+.58*w1+.34*w2)*lay;
    else if(pat==='ladder') q=(yy+.26*w1+.13*w2)*lay + CT[i*2];
    else if(pat==='twist') q=lay*((yy-.5)*CT[i*2]+twZ*CT[i*2+1]) + lay*(.24*w1+.12*w2);
    else { // raindrop — drilled dimples, layers ring out around each
      q=(yy+.22*w1+.11*w2)*lay;
      for(let k=0;k<NDR;k++){
        const dx=(xx-DR[k*3])*1.0, dy=(yy-DR[k*3+1])*asp, rr=DR[k*3+2];
        const d2=(dx*dx+dy*dy)/(rr*rr);
        q-=3.0/(1+d2*2.2);
      }
    }
    Q[j*BW+i]=q;
  }
}

// ---- PASS 2: relief lighting from the band gradient ----
G.loadPixels();
const px=G.pixels, sR=spTint[0], sG=spTint[1], sB=spTint[2];
const relK=relief*(.55+.8*en)*220/Math.max(6,lay);
const gAmt=grainAmt*(.6+.9*dens);
const vigK=1.15;
for(let j=0;j<BH;j++){
  const j0=Math.max(0,j-1)*BW, j1=Math.min(BH-1,j+1)*BW, jr=j*BW;
  const gy=(j/BW)*fq+camY, vy=(j/BH-.5);
  for(let i=0;i<BW;i++){
    const idx=jr+i;
    const q=Q[idx];
    const gqx=(Q[jr+Math.min(BW-1,i+1)]-Q[jr+Math.max(0,i-1)])*.5;
    const gqy=(Q[j1+i]-Q[j0+i])*.5;
    const ph=q*.5, f=ph-Math.floor(ph);
    let k=(f*512)|0; if(k<0)k=0; if(k>511)k=511;
    const r=PR[k], drdf=PD[k];
    const mixT=(r+1)*.5;
    const mi=md(Math.floor(ph),3)|0;
    const m=MET[mi];
    // surface slope along the light azimuth
    const slope=cl(drdf*.5*(gqx*lx+gqy*ly)*relK,-6,6);
    const lam=cl(.52-slope*.30,0,1.4);
    const sd=slope-tilt*2.2;
    const spec=specAmt/(1+sd*sd*3.4);
    // grain: fine tooth in billet coords, drifts with the camera
    const gx=(i/BW)*fq+camX;
    const gn=(nzAt(gx*11.3+7.1, gy*11.3+2.9)-.5)*gAmt;
    let R,Gc,B;
    if(xray){
      const e=cl(Math.abs(drdf)*.11,0,1);
      const v=.10+.13*mixT+.86*Math.pow(e,.75);
      R=DK[0]+(m[0]-DK[0])*v; Gc=DK[1]+(m[1]-DK[1])*v; B=DK[2]+(m[2]-DK[2])*v;
      R*=(1+gn*.6); Gc*=(1+gn*.6); B*=(1+gn*.6);
    } else {
      const sl=inkish? (.62+.5*lam) : (.34+.86*lam);
      R=(DK[0]+(m[0]-DK[0])*mixT)*sl; Gc=(DK[1]+(m[1]-DK[1])*mixT)*sl; B=(DK[2]+(m[2]-DK[2])*mixT)*sl;
      if(!inkish){ const sp=spec*(.25+.85*mixT)*82; R+=sR*sp/255; Gc+=sG*sp/255; B+=sB*sp/255; }
      R*=(1+gn); Gc*=(1+gn); B*=(1+gn);
    }
    // gentle plate vignette so the eye lands mid-frame
    const vx=(i/BW-.5), vg=1-vigK*.30*(vx*vx*1.1+vy*vy*1.5);
    R*=vg; Gc*=vg; B*=vg;
    const o=idx*4;
    px[o]=R<0?0:R>255?255:R; px[o+1]=Gc<0?0:Gc>255?255:Gc; px[o+2]=B<0?0:B>255?255:B; px[o+3]=255;
  }
}
G.updatePixels();

noStroke();
if(al<1){ push(); drawingContext.globalAlpha=al; image(G,0,0,W,Hh); pop(); }
else image(G,0,0,W,Hh);

// ---- forge scale: a couple of soft dark bloom patches drifting over the face ----
const nsp=Math.round(2+dens*3);
const dc=drawingContext, oldOp=dc.globalCompositeOperation;
dc.globalCompositeOperation='multiply';
for(let k=0;k<nsp;k++){
  const px0=(md(fr(k*7+90)+.023*Math.sin(T*.041+k*1.7)+.011*Math.sin(T*.093+k),1))*W;
  const py0=(md(fr(k*7+91)+.019*Math.cos(T*.037+k*2.3),1))*Hh;
  const rr=Math.min(W,Hh)*(.16+.20*fr(k*7+92))*sc;
  const rg=dc.createRadialGradient(px0,py0,0,px0,py0,rr);
  const aa=(.10+.13*fr(k*7+93))*al*(.5+.6*(1-en));
  rg.addColorStop(0,'rgba(28,26,22,'+aa.toFixed(4)+')');
  rg.addColorStop(1,'rgba(28,26,22,0)');
  dc.fillStyle=rg; dc.fillRect(px0-rr,py0-rr,rr*2,rr*2);
}
dc.globalCompositeOperation=oldOp;

blendMode(BLEND); dc.globalAlpha=1; dc.shadowBlur=0; noStroke(); noTint();
